def factorial(n):
    if n < 0:
        raise ValueError('Input must be a non-negative integer')
    if n == 0:
        return 1
    return n * factorial(n - 1)

def is_palindrome(s):
    cleaned = s.lower().replace(' ', '')
    return cleaned == cleaned[::-1]

def fibonacci(n):
    if n < 0:
        raise ValueError('Input must be a non-negative integer')
    if n == 0:
        return 0
    a, b = 0, 1
    for _ in range(1, n):
        a, b = b, a + b
    return b

